import{Z as t,e as s,f as r,a0 as a}from"./chunks/framework.DmpHOl9T.js";const p=JSON.parse('{"title":"Survey","description":"","frontmatter":{},"headers":[],"relativePath":"fields/survey.md","filePath":"fields/survey.md","lastUpdated":1781883127000}'),o={name:"fields/survey.md"};function i(n,e,l,d,c,h){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="survey" tabindex="-1">Survey <a class="header-anchor" href="#survey" aria-label="Permalink to &quot;Survey&quot;">​</a></h1><p>Use the Survey field to collect questionnaire responses with multiple presentation types: radio buttons, checkboxes, dropdown, Likert scale, star rating, and rank.</p><h2 id="presentation-types" tabindex="-1">Presentation Types <a class="header-anchor" href="#presentation-types" aria-label="Permalink to &quot;Presentation Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Presentation</th><th>Use when</th></tr></thead><tbody><tr><td>Radio</td><td>Single choice from a short list</td></tr><tr><td>Checkboxes</td><td>Multiple choices</td></tr><tr><td>Dropdown</td><td>Single choice from a longer list</td></tr><tr><td>Likert</td><td>Agreement or satisfaction scale</td></tr><tr><td>Rating</td><td>Star rating</td></tr><tr><td>Rank</td><td>Drag-and-drop preference ranking</td></tr></tbody></table><p>Text-based presentations are not included in the questionnaire Results tab.</p><h2 id="likert-scoring" tabindex="-1">Likert Scoring <a class="header-anchor" href="#likert-scoring" aria-label="Permalink to &quot;Likert Scoring&quot;">​</a></h2><p>For Likert presentations with <strong>static columns</strong>, enable <strong>Weighted score</strong> on the Columns table to assign a numeric score to each column.</p><p>Scoring is only available with static options. Dynamic or integration-driven option sources disable scoring automatically.</p><p>When scoring is enabled:</p><ul><li>Each submission’s Likert score is the sum of points for the selected columns.</li><li>Multi-row Likert fields sum points across all answered rows.</li><li>The Results tab shows the average score and maximum possible score per question.</li></ul><h3 id="likert-rows" tabindex="-1">Likert Rows <a class="header-anchor" href="#likert-rows" aria-label="Permalink to &quot;Likert Rows&quot;">​</a></h3><p>Enable <strong>Multiple rows</strong> to collect one scale response per statement. Row labels are configured separately from column labels. When only one row is configured, the field renders as a single-row Likert scale.</p><h2 id="rank-results" tabindex="-1">Rank Results <a class="header-anchor" href="#rank-results" aria-label="Permalink to &quot;Rank Results&quot;">​</a></h2><p>Rank submissions are aggregated in the Results tab using weighted position scoring. Higher-ranked options receive more weight in the bar chart.</p><h2 id="key-settings" tabindex="-1">Key Settings <a class="header-anchor" href="#key-settings" aria-label="Permalink to &quot;Key Settings&quot;">​</a></h2><ul><li><strong>Question</strong> - The question text shown to respondents.</li><li><strong>Presentation</strong> - The display type for this field.</li><li><strong>Static options / columns</strong> - Define choices or Likert columns.</li><li><strong>Likert rows</strong> - Optional statements for multi-row Likert fields.</li></ul><h2 id="results-tab" tabindex="-1">Results Tab <a class="header-anchor" href="#results-tab" aria-label="Permalink to &quot;Results Tab&quot;">​</a></h2><p>Survey fields that use options (radio, checkboxes, dropdown, Likert, rating, rank) appear on the form <strong>Results</strong> tab with response counts and option breakdowns. Likert fields with scoring enabled also show average scores.</p>',18)])])}const g=t(o,[["render",i]]);export{p as __pageData,g as default};
